import { useState } from "react";
import { WakeSlider } from "solen-design/react";

const [volume, setVolume] = useState(50);

<WakeSlider
  value={volume}
  onChange={setVolume}
  min={0}
  max={100}
  step={1}
  bars={32}
  height={56}
  restHeight={12}
  reach={6}
  skew={0.6}
  showValue={true}
  ariaLabel="Volume"
/>
